1101	\section{Expanding the Hilbert space and defining commuting observables}
1102	\label{sec:expanding}
1103	
1104	The next step of the analysis adjoins ancillary EPR registers to the
1105	players' state and lifts the strategy observables and measurements to the
1106	expanded state. The point of the construction is that the ancilla factor of
1107	each lifted observable carries the \emph{exact} Pauli commutation sign, so
1108	that the signs cancel and the lifted observables approximately commute for
1109	every tuple $\omega$.
1110	
1111	\begin{definition}[Expanded state]
1112		\label{def:expanded-state}
1113		\lean{MIPStarRE.QPBT.SixReg, MIPStarRE.QPBT.ProjectiveSetting.psiHat}
1114		\leanok
1115		\uses{lem:projective-strategy-setup, def:EPR}
1116		Recall that $M = 2^m$. Introduce registers $\mathsf{A}', \mathsf{A}'',
1117		\mathsf{B}', \mathsf{B}''$, each with Hilbert space isomorphic to
1118		$(\C^q)^{\ot M}$, and define the state
1119		\begin{equation}\label{eq:def-psihat}
1120			\ket{\hat{\psi}}_{\mathsf{A}\mathsf{A}'\mathsf{A}''\mathsf{B}\mathsf{B}'\mathsf{B}''}
1121			\,=\, (\ket{\psi})_{\mathsf{A}\mathsf{B}}
1122			\ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathsf{A}'\mathsf{A}''}
1123			\ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathsf{B}'\mathsf{B}''}\,,
1124		\end{equation}
1125		where $\ket{\psi}$ is the extended strategy state of the strategy
1126		under analysis (Lemma~\ref{lem:projective-strategy-setup} and the
1127		convention following it) and
1128		$\ket{\mathrm{EPR}_q}$ is the maximally entangled state on
1129		$\C^q \ot \C^q$ (Definition~\ref{def:EPR}). For the remainder of this
1130		chapter, as well as in Chapters~\ref{chap:qpbt-combining}
1131		and~\ref{chap:qpbt-extraction}, all approximations $\approx$ and
1132		$\simeq$ are evaluated with respect to the state $\ket{\hat{\psi}}$,
1133		unless stated otherwise.
1134	\end{definition}
1135	
1136	\begin{definition}[Expanded observables]
1137		\label{def:expanded-observables}
1138		\lean{MIPStarRE.QPBT.ProjectiveSetting.expObs}
1139		\leanok
1140		\uses{def:strategy-observables, def:expanded-state, lem:twisted-commutation}
1141		For all $W \in \{X,Z\}$, $r \in \F_q$, and $u \in \F_q^m$, define the
1142		observable
1143		\begin{equation}\label{eq:lc-23}
1144			\hat{W}^r(u) \,=\, W^r(u) \ot \tau^W(r \cdot \mathrm{ind}_m(u))\,,
1145		\end{equation}
1146		where $W^r(u)$ is the strategy observable of~\eqref{eq:qld-strat-obs}
1147		and $\tau^W(r \cdot \mathrm{ind}_m(u))$ is the generalized Pauli
1148		observable acting on $(\C^q)^{\ot M}$, introduced in
1149		Chapter~\ref{chap:qpbt-algebra}
1150		(see Lemma~\ref{lem:twisted-commutation}). As a product
1151		of two observables with eigenvalues $\pm 1$ acting on disjoint
1152		registers, $\hat{W}^r(u)$ is itself an observable with eigenvalues
1153		$\pm 1$. If $W^r(u)$ is viewed as acting on register $\mathsf{A}$, then
1154		$\hat{W}^r(u)$ is viewed as acting on registers
1155		$\mathsf{A}\mathsf{A}'$, with the $\tau^W$ factor acting on
1156		$\mathsf{A}'$. The registers are generally indicated by subscripts, as
1157		in $(\hat{W}^r(u))_{\mathsf{A}\mathsf{A}'}$ or
1158		$(\hat{W}^r(u))_{\mathsf{B}\mathsf{A}''}$, the latter having the
1159		strategy factor on $\mathsf{B}$ and the Pauli factor on
1160		$\mathsf{A}''$.
1161	\end{definition}
1162	
1163	\begin{definition}[Expanded point measurements]
1164		\label{def:expanded-point-measurement}
1165		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointOp}
1166		\lean{MIPStarRE.QPBT.ProjectiveSetting.tauPointProj}
1167		\lean{MIPStarRE.QPBT.ProjectiveSetting.pointMeasExp}
1168		\leanok
1169		\uses{def:expanded-observables, lem:pauli-observable-expansion, def:low-degree-encoding, def:subfield-trace}
1170		For $W \in \{X,Z\}$, $u \in \F_q^m$ and $a \in \F_q$, define
1171		\[
1172			\hat{M}^{(\mathrm{Point},W),u}_a \,=\, \E_{r \in \F_q} (-1)^{\tr(ar)} \, \hat{W}^r(u)\,,
1173		\]
1174		and define the projector
1175		\begin{equation}\label{eq:qld-point-obs-def}
1176			\tau^{W,u}_a \,=\, \tau^W_{[g_\cdot(u) = a]}
1177			\,=\, \sum_{h \in \F_q^{M} \colon h \cdot \mathrm{ind}_m(u) = a} \tau^W_h\,,
1178		\end{equation}
1179		where $\{\tau^W_h\}_{h \in \F_q^{M}}$ are the joint eigenprojectors of
1180		the generalized Pauli $W$-observables
1181		(see Lemma~\ref{lem:pauli-observable-expansion}).
1182	\end{definition}
1183	
1184	\begin{lemma}[Convolution and projectivity of expanded point measurements]
1185		\label{lem:expanded-point-measurement-properties}
1186		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointOp_eq_convolution}
1187		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointOp_nonneg}
1188		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointOp_sum_eq_one}
1189		\lean{MIPStarRE.QPBT.ProjectiveSetting.pointMeasExp_isProjective}
1190		\leanok
1191		\uses{def:expanded-point-measurement}
1192		For either player, $W \in \{X,Z\}$, $u \in \F_q^m$ and $a \in \F_q$,
1193		the expanded point effects have the convolution form
1194		\[
1195			\hat{M}^{(\mathrm{Point},W),u}_a
1196			\,=\, \sum_{\substack{a',a'' \in \F_q \\ a' + a'' = a}}
1197			M^{(\mathrm{Point},W),u}_{a'} \ot \tau^{W,u}_{a''}\,.
1198		\]
1199		Each effect is positive semidefinite, and
1200		$\sum_{a \in \F_q}\hat{M}^{(\mathrm{Point},W),u}_a=\Id$.
1201		Moreover, each $\hat{M}^{(\mathrm{Point},W),u}_a$ is a projection
1202		and $\{\hat{M}^{(\mathrm{Point},W),u}_a\}_{a \in \F_q}$ is a projective
1203		measurement.
1204	\end{lemma}
1205	\begin{proof}
1206		\leanok
1207		\uses{def:strategy-observables, def:expanded-observables,
1208		lem:pauli-observable-expansion, prop:fourier-fact-scalar,
1209		lem:operator-average-scalar-constant, lem:point-observable-multiplication,
1210		lem:twisted-commutation}
1211		Expand both tensor factors of $\hat{W}^r(u)$ and average over $r$.
1212		Character orthogonality retains exactly the terms with $a'+a''=a$,
1213		giving the convolution formula. Its summands are tensor products of
1214		positive semidefinite operators, proving positivity. Summing over $a$
1215		removes the convolution constraint; completeness of the strategy and
1216		Pauli measurements then gives the identity.
1217		For projectivity, multiplication of point observables and of Pauli
1218		observables gives $\hat{W}^r(u)\hat{W}^s(u)=\hat{W}^{r+s}(u)$.
1219		Squaring the Fourier average defining an effect and translating the
1220		uniform summation variable therefore gives the same effect.
1221		Positivity supplies self-adjointness, so each effect is a projection.
1222	\end{proof}
1223	
1224	\begin{definition}[Trace-coarse-grained point projections]
1225		\label{def:expanded-point-trace-projection}
1226		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointTrace}
1227		\leanok
1228		\uses{def:expanded-point-measurement, lem:expanded-point-measurement-properties,
1229		def:expanded-observables, def:subfield-trace}
1230		For fixed $u \in \F_q^m$, $r \in \F_q$ and $b \in \F_2$, define the
1231		projection
1232		\begin{equation}\label{eq:qld-def-mptur}
1233			\hat{M}^{(\mathrm{Point},W),u,r}_b \,=\, \sum_{a \in \F_q \colon \tr(ar) = b} \hat{M}^{(\mathrm{Point},W),u}_a\,,
1234		\end{equation}
1235		The register conventions are those of
1236		Definition~\ref{def:expanded-observables}.
1237	\end{definition}
1238	
1239	\begin{lemma}[Trace coarse-graining identity]
1240		\label{lem:expanded-point-trace-half-add}
1241		\lean{MIPStarRE.QPBT.ProjectiveSetting.expPointTrace_eq_half_add}
1242		\leanok
1243		\uses{def:expanded-point-trace-projection, def:expanded-observables}
1244		For either player, $W \in \{X,Z\}$, $u \in \F_q^m$, every $r \in \F_q$
1245		(including $r=0$), and $b \in \F_2$, we have
1246		\begin{equation}\label{eq:lc-22}
1247			\hat{M}^{(\mathrm{Point},W),u,r}_b \,=\, \frac{1}{2} \Big( \Id + (-1)^b\, \hat{W}^r(u) \Big)\,.
1248		\end{equation}
1249	\end{lemma}
1250	\begin{proof}
1251		\leanok
1252		\uses{lem:expanded-point-measurement-properties, prop:fourier-fact-scalar,
1253		lem:operator-average-scalar-constant}
1254		Fourier inversion gives
1255		$\sum_a(-1)^{\tr(ar)}\hat{M}^{(\mathrm{Point},W),u}_a=\hat{W}^r(u)$.
1256		The two trace classes sum to $\Id$ by completeness, and their difference
1257		is this signed sum. Adding or subtracting these two identities and
1258		dividing by two proves the formula.
1259	\end{proof}
